package real

import "strings"

// concealedMarkers are substrings of platform clipboard format names that password managers and other
// tools set to ask clipboard tools not to record a copy: the three macOS nspasteboard conventions
// (ConcealedType, TransientType, AutoGeneratedType, the same set the 1.x app checks), the Windows
// exclude-from-history flag, and the KDE password manager hint that X11 owners such as KeePassXC advertise
// as the raw target x-kde-passwordManagerHint (matched case-insensitively). The X11 names come from MyGo's
// raw target list and are not verified on a live X11 session in this build; see the rig journey J06.
var concealedMarkers = []string{
	"concealed",
	"transienttype",
	"autogeneratedtype",
	"excludeclipboardcontent",
	"passwordmanagerhint",
}

// isConcealedClipboard reports whether any format name carries a concealed marker.
func isConcealedClipboard(formats []string) bool {
	for _, format := range formats {
		lower := strings.ToLower(format)
		for _, marker := range concealedMarkers {
			if strings.Contains(lower, marker) {
				return true
			}
		}
	}
	return false
}
